CREATE TABLE IF NOT EXISTS app_users (id CHAR(32) PRIMARY KEY,name VARCHAR(100) NOT NULL,username VARCHAR(60) NOT NULL UNIQUE,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(10) NOT NULL,session_version INT NOT NULL DEFAULT 1,active TINYINT NOT NULL DEFAULT 1,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS app_phones (id CHAR(32) PRIMARY KEY,imei1 CHAR(15) NOT NULL,imei2 CHAR(15) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS app_aliases (imei CHAR(15) PRIMARY KEY,phone_id CHAR(32) NOT NULL,slot TINYINT NOT NULL,UNIQUE KEY phone_slot(phone_id,slot),FOREIGN KEY(phone_id) REFERENCES app_phones(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS app_trades (id CHAR(32) PRIMARY KEY,phone_id CHAR(32) NOT NULL,`date` CHAR(10) NOT NULL,kind VARCHAR(10) NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,national_id CHAR(10) NOT NULL,contact VARCHAR(16) NOT NULL DEFAULT '',model VARCHAR(100) NOT NULL,color VARCHAR(100) NOT NULL,memory VARCHAR(100) NOT NULL,`condition` VARCHAR(10) NOT NULL,registration VARCHAR(15) NOT NULL,notes TEXT NOT NULL,created_by CHAR(32) NOT NULL,created_name VARCHAR(100) NOT NULL,updated_by CHAR(32) NOT NULL,updated_name VARCHAR(100) NOT NULL,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,deleted_at VARCHAR(30) NULL,version INT NOT NULL DEFAULT 1,INDEX trade_phone(phone_id),INDEX trade_date(`date`),FOREIGN KEY(phone_id) REFERENCES app_phones(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS app_audit (id CHAR(32) PRIMARY KEY,trade_id CHAR(32) NOT NULL,action VARCHAR(20) NOT NULL,actor_id CHAR(32) NOT NULL,actor_name VARCHAR(100) NOT NULL,at VARCHAR(30) NOT NULL,snapshot LONGTEXT NOT NULL,INDEX audit_trade(trade_id),FOREIGN KEY(trade_id) REFERENCES app_trades(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS app_user_events (id CHAR(32) PRIMARY KEY,user_id CHAR(32) NOT NULL,action VARCHAR(20) NOT NULL,actor_id CHAR(32) NOT NULL,at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS app_login_limits (id CHAR(64) PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,reset_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS app_imports(source_key CHAR(64) PRIMARY KEY,trade_id CHAR(32) NOT NULL,FOREIGN KEY(trade_id) REFERENCES app_trades(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
